  "inlineSchema": "// SQLite datasource - bundled file DB suitable for single-site server\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// User accounts\nmodel User {\n  id        String   @id @default(cuid())\n  username  String   @unique\n  password  String\n  fullName  String\n  role      String   @default(\"user\") // user | admin\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Patient information\nmodel Patient {\n  id                String        @id @default(cuid())\n  code              String        @unique\n  queueNumber       String? // Mã số thứ tự (reset mỗi ngày)\n  fullName          String\n  phone             String?\n  gender            String?\n  birthDate         DateTime?\n  address           String?\n  visitPurpose      String        @default(\"both\") // examination | refraction | both\n  visitStatus       String        @default(\"waiting\") // waiting | in_progress | completed (legacy)\n  examinationStatus String        @default(\"waiting\") // waiting | in_progress | completed\n  refractionStatus  String        @default(\"waiting\") // waiting | in_progress | completed\n  // Thị lực ban đầu khi đến khám\n  initialVaOd       String? // Thị lực mắt phải\n  initialVaOs       String? // Thị lực mắt trái\n  hasGlasses        Boolean       @default(false) // Có đeo kính không\n  visitReason       String? // Lý do đến khám\n  notes             String? // Ghi chú\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n  refractions       Refraction[]\n  examinations      Examination[]\n  invoices          Invoice[]\n}\n\n// Refraction examination results\nmodel Refraction {\n  id        String  @id @default(cuid())\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  patientId String\n\n  // 1. Khúc xạ khách quan (Skiascopy) - không có VA\n  skiasOdSph     String?\n  skiasOdCyl     String?\n  skiasOdAxis    String?\n  skiasOsSph     String?\n  skiasOsCyl     String?\n  skiasOsAxis    String?\n  hasCycloplegia Boolean @default(false) // Liệt điều tiết\n\n  // 2. Khúc xạ chủ quan (Subjective Refraction) - có VA\n  subjOdSph  String?\n  subjOdCyl  String?\n  subjOdAxis String?\n  subjOdVa   String? // Visual Acuity\n  subjOsSph  String?\n  subjOsCyl  String?\n  subjOsAxis String?\n  subjOsVa   String?\n\n  // 3. Kính điều chỉnh (Prescription) - dùng để recommend\n  odSph  String?\n  odCyl  String?\n  odAxis String?\n  odVa   String? // Visual Acuity\n  osSph  String?\n  osCyl  String?\n  osAxis String?\n  osVa   String?\n\n  // Thông số bổ sung\n  odAdd    String? // Độ ADD mắt phải\n  osAdd    String? // Độ ADD mắt trái\n  pd       String? // Khoảng cách đồng tử (Pupillary Distance)\n  lensType String? // Loại kính: da_trong | hai_trong | don_trong_xa | don_trong_gan\n\n  // Examination date and notes\n  examDate  DateTime @default(now())\n  notes     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Medical examination (doctor's diagnosis)\nmodel Examination {\n  id          String   @id @default(cuid())\n  patient     Patient  @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  patientId   String\n  symptoms    String? // Triệu chứng\n  diagnosis   String? // Chẩn đoán\n  treatment   String? // Điều trị\n  medications String? // Thuốc kê đơn\n  examDate    DateTime @default(now())\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// Product (glasses, lenses, medicines)\nmodel Product {\n  id           String        @id @default(cuid())\n  code         String        @unique\n  name         String\n  category     String        @default(\"glasses\") // glasses | lenses | medicine\n  lensCategory String? // Phân loại tròng: don_trong | hai_trong | da_trong\n  manufacturer String?\n  sphRange     String? // Spherical range\n  cylRange     String? // Cylinder range\n  addRange     String? // ADD range (cho 2 tròng và đa tròng)\n  leftRegion   String? // Miền bên trái (cho 2 tròng, đa tròng)\n  rightRegion  String? // Miền bên phải (cho 2 tròng, đa tròng)\n  material     String? // Material (AS, CR, etc.)\n  price        Int           @default(0)\n  quantity     Int           @default(0)\n  minStock     Int           @default(5)\n  expiresAt    DateTime?\n  imageUrl     String?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  items        InvoiceItem[]\n}\n\n// Invoice\nmodel Invoice {\n  id              String        @id @default(cuid())\n  code            String        @unique\n  patient         Patient       @relation(fields: [patientId], references: [id])\n  patientId       String\n  type            String        @default(\"glasses\") // glasses | medicine\n  status          String        @default(\"UNPAID\") // UNPAID | PAID | CANCELLED\n  subtotal        Int           @default(0)\n  discount        Int           @default(0)\n  voucherCode     String? // Mã voucher\n  voucherDiscount Int           @default(0) // Giảm giá từ voucher\n  processingFee   Int           @default(0) // Phí gia công (cho kính)\n  shippingFee     Int           @default(0) // Phí vận chuyển\n  serviceFee      Int           @default(0) // Phí dịch vụ\n  tax             Int           @default(0)\n  total           Int           @default(0)\n  notes           String? // Ghi chú\n  instructions    String? // Hướng dẫn sử dụng\n  dosage          String? // Liều lượng (cho thuốc)\n  followUpDate    DateTime? // Ngày hẹn tái khám\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  items           InvoiceItem[]\n}\n\n// Invoice items\nmodel InvoiceItem {\n  id         String  @id @default(cuid())\n  invoice    Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  invoiceId  String\n  product    Product @relation(fields: [productId], references: [id])\n  productId  String\n  quantity   Int     @default(1)\n  unitPrice  Int     @default(0)\n  totalPrice Int     @default(0)\n}\n\n// Voucher\nmodel Voucher {\n  id          String   @id @default(cuid())\n  code        String   @unique\n  description String?\n  type        String   @default(\"percent\") // percent | fixed\n  value       Int // Giá trị % hoặc số tiền\n  minAmount   Int      @default(0) // Giá trị đơn hàng tối thiểu\n  maxDiscount Int? // Giảm tối đa (cho percent)\n  startDate   DateTime\n  endDate     DateTime\n  isActive    Boolean  @default(true)\n  usageLimit  Int? // Số lần sử dụng tối đa\n  usageCount  Int      @default(0) // Số lần đã sử dụng\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// Settings\nmodel Setting {\n  id        String   @id @default(cuid())\n  key       String   @unique\n  value     String\n  updatedAt DateTime @updatedAt\n}\n",
